import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import './Aiiot.css'; // Ensure this file exists, or the inline styles below will handle most things

const ProjectDetail = () => {
  const { projectId } = useParams();
  const [activeSection, setActiveSection] = useState('overview');

  // Scroll to top on mount
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [projectId]);

  // Handle Scroll Spy for Sticky Nav
  useEffect(() => {
    const handleScroll = () => {
      const sections = ['overview', 'features', 'specifications', 'applications', 'downloads'];
      const scrollPosition = window.scrollY + 150; // Offset for header height

      for (const section of sections) {
        const element = document.getElementById(section);
        if (element && element.offsetTop <= scrollPosition && (element.offsetTop + element.offsetHeight) > scrollPosition) {
          setActiveSection(section);
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 140; // Height of main header + sub-nav
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;
      window.scrollTo({ top: offsetPosition, behavior: 'smooth' });
    }
  };

  // Expanded Data to match the "Prana Air" depth
  const projectsData = {
    'intelligent-sensor': {
      title: 'Aqi monitoring',
      subtitle: 'Hyper-local Air Quality Monitoring System',
      tagline: 'Precision sensing for a healthier tomorrow.',
      mainImage: '/sensor_modules/module2.jpg',
      description: 'An advanced IoT device designed to continuously monitor hyper-local air quality parameters. Unlike standard city-wide monitors, this module provides street-level accuracy for safer urban living.',
      fullDescription: `The Intelligent Sensor Module bridges the gap between general weather data and the actual air you breathe. Designed for smart cities and modern campuses, it integrates high-precision laser scattering sensors to detect particulate matter (PM2.5, PM10) and electrochemical sensors for toxic gases. With built-in edge computing, it doesn't just report data—it analyzes trends to provide actionable health alerts in real-time.`,
      features: [
        { title: 'Laser Precision', desc: 'Dual-laser scattering for 99% accuracy in PM detection.' },
        { title: 'Real-time Alerts', desc: 'Instant notifications via App & SMS when levels breach safety limits.' },
        { title: 'Edge Analytics', desc: 'On-board processing reduces cloud latency and data costs.' },
        { title: 'Weather Proof', desc: 'IP67 rated enclosure designed for harsh Indian monsoons.' },
        { title: 'Solar Ready', desc: 'Optional solar panel integration for off-grid deployment.' },
        { title: 'Seamless Connectivity', desc: 'Supports Wi-Fi, LoRaWAN, and 4G/LTE modules.' }
      ],
      applications: [
        { title: 'Smart Cities', icon: '🏙️', desc: 'Street-level pollution mapping for urban planning.' },
        { title: 'Schools', icon: '🎓', desc: 'Ensuring safe outdoor playtime for children.' },
        { title: 'Industrial Zones', icon: '🏭', desc: 'Compliance monitoring for factory emissions.' },
        { title: 'Hospitals', icon: '🏥', desc: 'Protecting sensitive patients from airborne contaminants.' }
      ],
      specifications: [
        { label: 'Particulate Matter', value: 'PM1.0, PM2.5, PM10' },
        { label: 'Gas Sensors', value: 'NO2, SO2, CO, O3, VOCs' },
        { label: 'Response Time', value: '< 3 seconds' },
        { label: 'Connectivity', value: 'Wi-Fi / GSM / LoRaWAN' },
        { label: 'Power Input', value: '5V DC / Solar 12V' },
        { label: 'Operating Temp', value: '-10°C to 65°C' }
      ],
      brochureUrl: '#'
    },
    'water-level': {
      title: 'Smart Water Level Monitor',
      subtitle: 'Early Warning Flood Detection System',
      tagline: 'Predict. Prepare. Protect.',
      mainImage: '/sensor_modules/water_monitor.jpg',
      description: 'A robust solution for real-time water level tracking. Designed to mitigate flood risks by providing early warnings to authorities and communities.',
      fullDescription: `Our Smart Water Level Monitoring system is more than just a sensor; it is a community lifeline. By deploying ultrasonic and hydrostatic sensors along riverbanks and dams, the system tracks water level rises with centimeter-level precision. The integrated AI model analyzes historical rainfall data against current water levels to predict flood risks hours in advance, giving authorities crucial time to act.`,
      features: [
        { title: 'Ultrasonic Accuracy', desc: 'Non-contact measurement accurate to ±2cm.' },
        { title: 'Flood Prediction AI', desc: 'Machine learning models that forecast rising trends.' },
        { title: 'Multi-Channel Alerts', desc: 'Simultaneous alerts via Siren, SMS, and Mobile App.' },
        { title: 'Rugged Design', desc: 'Anti-corrosion materials for long-term water exposure.' },
        { title: 'Long Range', desc: 'LoRa connectivity transmits data up to 15km line-of-sight.' },
        { title: 'Battery Backup', desc: '7-day battery life ensures operation during power outages.' }
      ],
      applications: [
        { title: 'River Banks', icon: '🌊', desc: 'Monitoring seasonal overflow and flash floods.' },
        { title: 'Dams & Reservoirs', icon: '🏗️', desc: 'Automated water release management.' },
        { title: 'Urban Drainage', icon: '🏙️', desc: 'Preventing waterlogging in city underpasses.' },
        { title: 'Agriculture', icon: '🌾', desc: 'Optimizing irrigation water usage.' }
      ],
      specifications: [
        { label: 'Sensor Type', value: 'Ultrasonic / Hydrostatic' },
        { label: 'Range', value: '0.2m to 20m' },
        { label: 'Accuracy', value: '±0.5% F.S.' },
        { label: 'Communication', value: 'LoRaWAN / 4G LTE' },
        { label: 'IP Rating', value: 'IP68 Submersible' },
        { label: 'Alert Latency', value: 'Instant (<1s)' }
      ],
      brochureUrl: '#'
    },
    'digital-water': {
      title: 'Digital Water Distribution',
      subtitle: 'Smart Network Management Twin',
      tagline: 'Visualizing the flow of life.',
      mainImage: '/sensor_modules/water_authorityy.jpeg',
      description: 'A digital twin solution for urban water networks. Monitor flow, detect leaks, and optimize pressure in real-time.',
      fullDescription: `The Digital Water Distribution system brings visibility to underground infrastructure. By creating a live digital replica of the pipeline network, utility companies can pinpoint leaks, identify pressure drops, and balance supply against demand. This reduces non-revenue water (NRW) loss and ensures equitable water distribution across all city wards.`,
      features: [
        { title: 'Digital Twin', desc: '3D visualization of the entire pipe network.' },
        { title: 'Leak Detection', desc: 'Acoustic sensors identify micro-leaks before they burst.' },
        { title: 'Pressure Optimization', desc: 'Auto-regulates valves to maintain constant pressure.' },
        { title: 'Consumption Analytics', desc: 'Detailed usage reports for predictive supply planning.' },
        { title: 'Retrofit Ready', desc: 'Compatible with existing mechanical meters via add-ons.' },
        { title: 'Remote Valve Control', desc: 'Shut off sections remotely during maintenance.' }
      ],
      applications: [
        { title: 'Municipalities', icon: '🏛️', desc: 'City-wide water distribution management.' },
        { title: 'Gated Communities', icon: '🏡', desc: 'Billing and leak management for large complexes.' },
        { title: 'Industrial Parks', icon: '🏭', desc: 'Process water monitoring and efficiency.' },
        { title: 'Hotels', icon: '🏨', desc: 'Guest usage monitoring and conservation.' }
      ],
      specifications: [
        { label: 'Flow Rate Range', value: '0.1 to 500 m³/h' },
        { label: 'Pressure Range', value: '0 - 16 Bar' },
        { label: 'Data Interval', value: 'Configurable (1min - 24hr)' },
        { label: 'Battery Life', value: '5 Years (Lithium)' },
        { label: 'Cloud Platform', value: 'AWS / Azure IoT' },
        { label: 'Pipe Size', value: 'DN15 to DN200' }
      ],
      brochureUrl: '#'
    },
     'startup-skill': {
      title: 'Startup & Skill Development',
      subtitle: 'Fostering Innovation and Entrepreneurship',
      tagline: 'Empowering the next generation of innovators.',
      mainImage: '/sensor_modules/skill.jpg',
      description: 'Fostering a vibrant startup ecosystem and providing skill development programs centered around our IoT solutions.',
      fullDescription: `
        Our Startup & Skill Development initiative provides aspiring entrepreneurs, students, and technology enthusiasts with comprehensive training, structured mentorship, and essential resources needed to transform ideas into impactful solutions. Participants gain access to hands-on IoT workshops, business incubation support, and state-of-the-art hardware and software tools—empowering them to innovate, prototype, and build real-world products with confidence.
      `,
      features: [
        { title: 'IoT Bootcamps', desc: 'Intensive hands-on training in embedded systems.' },
        { title: 'Mentorship', desc: 'Guidance from industry experts and successful founders.' },
        { title: 'Prototyping Labs', desc: 'Access to 3D printers, CNCs, and electronics benches.' },
        { title: 'Incubation', desc: 'Office space and resources for early-stage startups.' },
        { title: 'Funding Access', desc: 'Connections to angel investors and grant bodies.' },
        { title: 'Certifications', desc: 'Industry-recognized certificates upon completion.' }
      ],
      applications: [
          { title: 'Students', icon: '👨‍🎓', desc: 'Skill enhancement and project guidance.' },
          { title: 'Entrepreneurs', icon: '🚀', desc: 'Support for launching new ventures.' },
          { title: 'Professionals', icon: '💼', desc: 'Upskilling in IoT and AI technologies.' },
          { title: 'Institutions', icon: '🏫', desc: 'Curriculum development and faculty training.' }
      ],
      specifications: [
        { label: 'Program Duration', value: 'Flexible (Weeks to Months)' },
        { label: 'Batch Size', value: '20-30 Participants' },
        { label: 'Focus Areas', value: 'IoT, AI, Robotics, Cloud' },
        { label: 'Hardware Kits', value: 'Provided for hands-on' },
        { label: 'Certification', value: 'Yes (Partnered)' },
        { label: 'Placement Support', value: 'Available' }
      ],
      brochureUrl: '#'
    },
  };

  const project = projectsData[projectId];

  if (!project) {
    return (
      <div style={{ padding: '5rem 2rem', textAlign: 'center', minHeight: '80vh', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center' }}>
        <h1 style={{ color: '#1e293b', marginBottom: '1rem' }}>Project Not Found</h1>
        <Link to="/" style={{ padding: '0.75rem 1.5rem', background: '#3b82f6', color: 'white', borderRadius: '0.5rem', textDecoration: 'none' }}>
          Back to Home
        </Link>
      </div>
    );
  }

  // --- STYLES ---
  // (In a real app, move these to a CSS Module)
  const styles = {
    stickyNav: {
      position: 'sticky',
      top: '5rem', // Adjust based on your main header height
      zIndex: 40,
      backgroundColor: 'rgba(255, 255, 255, 0.9)',
      backdropFilter: 'blur(10px)',
      borderBottom: '1px solid #e2e8f0',
      boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)',
      overflowX: 'auto', // For mobile scrolling
    },
    navItem: (isActive) => ({
      padding: '1rem 1.5rem',
      color: isActive ? '#2563eb' : '#64748b',
      fontWeight: isActive ? 600 : 500,
      borderBottom: isActive ? '3px solid #2563eb' : '3px solid transparent',
      cursor: 'pointer',
      whiteSpace: 'nowrap',
      transition: 'all 0.2s ease',
    }),
    sectionHeading: {
      fontSize: '2rem',
      fontWeight: 700,
      color: '#1e293b',
      marginBottom: '1rem',
      position: 'relative',
      display: 'inline-block',
    },
    featureCard: {
      background: 'white',
      padding: '2rem',
      borderRadius: '1rem',
      border: '1px solid #e2e8f0',
      transition: 'all 0.3s ease',
      cursor: 'default',
    },
    specRow: (isEven) => ({
      display: 'flex',
      borderBottom: '1px solid #e2e8f0',
      backgroundColor: isEven ? '#f8fafc' : 'white',
    }),
    specLabel: {
      width: '40%',
      padding: '1rem',
      fontWeight: 600,
      color: '#475569',
      borderRight: '1px solid #e2e8f0',
    },
    specValue: {
      width: '60%',
      padding: '1rem',
      color: '#1e293b',
      fontWeight: 500,
    }
  };

  return (
    <div className="project-detail-page" style={{ background: '#ffffff', minHeight: '100vh' }}>
      
      {/* 1. TOP SUB-HEADER (Back Link) */}
      <div style={{ background: '#f8fafc', padding: '1rem 2rem', borderBottom: '1px solid #e2e8f0' }}>
        <div style={{ maxWidth: '80rem', margin: '0 auto' }}>
          <Link to="/" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.5rem', color: '#64748b', textDecoration: 'none', fontWeight: 500, fontSize: '0.9rem' }}>
            ← Back to All Solutions
          </Link>
        </div>
      </div>

      {/* 2. HERO SECTION */}
      <section style={{ 
        position: 'relative', 
        height: '60vh', 
        minHeight: '500px', 
        display: 'flex', 
        alignItems: 'center', 
        backgroundColor: '#1e293b', // Fallback
        overflow: 'hidden'
      }}>
        {/* Background Image with Overlay */}
        <div style={{
          position: 'absolute',
          top: 0, left: 0, right: 0, bottom: 0,
          backgroundImage: `url(${project.mainImage})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          opacity: 0.4
        }}></div>
        <div style={{
          position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
          background: 'linear-gradient(to right, rgba(15, 23, 42, 0.95) 0%, rgba(15, 23, 42, 0.6) 100%)'
        }}></div>

        {/* Hero Content */}
        <div style={{ maxWidth: '80rem', margin: '0 auto', padding: '0 2rem', position: 'relative', zIndex: 10, width: '100%' }}>
          <span style={{ 
            color: '#93c5fd', 
            fontWeight: 600, 
            letterSpacing: '1px', 
            textTransform: 'uppercase', 
            fontSize: '0.875rem', 
            marginBottom: '1rem', 
            display: 'block' 
          }}>
            AI-IoT Solution
          </span>
          <h1 style={{ 
            fontSize: 'clamp(2.5rem, 5vw, 4rem)', 
            fontWeight: 800, 
            color: 'white', 
            marginBottom: '1rem', 
            lineHeight: 1.1 
          }}>
            {project.title}
          </h1>
          <p style={{ 
            fontSize: 'clamp(1.25rem, 2vw, 1.5rem)', 
            color: '#e2e8f0', 
            marginBottom: '2rem', 
            maxWidth: '600px',
            fontWeight: 300
          }}>
            {project.subtitle}
          </p>
          <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
            <button 
              onClick={() => scrollToSection('specifications')}
              style={{ 
                padding: '1rem 2rem', 
                background: '#3b82f6', 
                color: 'white', 
                border: 'none', 
                borderRadius: '0.5rem', 
                fontWeight: 600, 
                fontSize: '1rem', 
                cursor: 'pointer',
                transition: 'background 0.3s'
              }}
            >
              View Specifications
            </button>
            <button style={{ 
              padding: '1rem 2rem', 
              background: 'transparent', 
              color: 'white', 
              border: '2px solid rgba(255,255,255,0.3)', 
              borderRadius: '0.5rem', 
              fontWeight: 600, 
              fontSize: '1rem', 
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: '0.5rem'
            }}>
              Download Brochure ⬇
            </button>
          </div>
        </div>
      </section>

      {/* 3. STICKY SUB-NAVIGATION */}
      <div style={styles.stickyNav}>
        <div style={{ maxWidth: '80rem', margin: '0 auto', display: 'flex' }}>
          {['Overview', 'Features', 'Specifications', 'Applications', 'Downloads'].map((item) => {
            const id = item.toLowerCase();
            return (
              <div 
                key={id}
                onClick={() => scrollToSection(id)}
                style={styles.navItem(activeSection === id)}
              >
                {item}
              </div>
            );
          })}
        </div>
      </div>

      {/* 4. MAIN CONTENT WRAPPER */}
      <div style={{ maxWidth: '64rem', margin: '0 auto', padding: '0 2rem' }}>

        {/* --- OVERVIEW SECTION --- */}
        <section id="overview" style={{ padding: '6rem 0', borderBottom: '1px solid #f1f5f9' }}>
          <div style={{ textAlign: 'center', maxWidth: '48rem', margin: '0 auto 4rem auto' }}>
            <h2 style={styles.sectionHeading}>Overview</h2>
            <p style={{ fontSize: '1.25rem', color: '#64748b', lineHeight: 1.8 }}>
              {project.description}
            </p>
          </div>
          <div style={{ display: 'flex', gap: '4rem', flexDirection: 'column' }}>
            <div style={{ fontSize: '1.1rem', color: '#334155', lineHeight: 1.8, columns: '2 300px', gap: '4rem' }}>
              {project.fullDescription}
            </div>
          </div>
        </section>

        {/* --- FEATURES SECTION --- */}
        <section id="features" style={{ padding: '6rem 0', borderBottom: '1px solid #f1f5f9' }}>
          <h2 style={styles.sectionHeading}>Key Features</h2>
          <p style={{ color: '#64748b', marginBottom: '3rem', fontSize: '1.1rem' }}>
            Designed for reliability, accuracy, and ease of use in critical environments.
          </p>
          
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '2rem' }}>
            {project.features.map((feature, idx) => (
              <div key={idx} className="feature-card" style={styles.featureCard}
                onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-5px)'; e.currentTarget.style.boxShadow = '0 10px 25px -5px rgba(0,0,0,0.1)'; }}
                onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.boxShadow = 'none'; }}
              >
                <div style={{ width: '3rem', height: '3rem', background: '#eff6ff', borderRadius: '0.5rem', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '1.5rem' }}>
                  <span style={{ color: '#2563eb', fontSize: '1.5rem' }}>✓</span>
                </div>
                <h3 style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.75rem' }}>
                  {feature.title}
                </h3>
                <p style={{ color: '#64748b', lineHeight: 1.6 }}>
                  {feature.desc}
                </p>
              </div>
            ))}
          </div>
        </section>

        {/* --- SPECIFICATIONS SECTION --- */}
        <section id="specifications" style={{ padding: '6rem 0', borderBottom: '1px solid #f1f5f9' }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '4rem', alignItems: 'start' }}>
            <div>
              <h2 style={styles.sectionHeading}>Technical Specifications</h2>
              <p style={{ color: '#64748b', marginBottom: '2rem' }}>
                Detailed performance metrics and hardware capabilities.
              </p>
              <div style={{ border: '1px solid #e2e8f0', borderRadius: '0.75rem', overflow: 'hidden' }}>
                {project.specifications.map((spec, idx) => (
                  <div key={idx} style={styles.specRow(idx % 2 === 0)}>
                    <div style={styles.specLabel}>{spec.label}</div>
                    <div style={styles.specValue}>{spec.value}</div>
                  </div>
                ))}
              </div>
            </div>
            {/* Spec Image/Graphic */}
            <div style={{ background: '#f8fafc', padding: '2rem', borderRadius: '1rem', textAlign: 'center' }}>
              <img 
                src={project.mainImage} 
                alt="Technical Diagram" 
                style={{ width: '100%', borderRadius: '0.5rem', mixBlendMode: 'multiply' }} 
              />
              <p style={{ marginTop: '1rem', fontSize: '0.875rem', color: '#94a3b8' }}>
                *Actual product appearance may vary slightly based on configuration.
              </p>
            </div>
          </div>
        </section>

        {/* --- APPLICATIONS SECTION --- */}
        <section id="applications" style={{ padding: '6rem 0', borderBottom: '1px solid #f1f5f9' }}>
          <h2 style={styles.sectionHeading}>Applications</h2>
          <p style={{ color: '#64748b', marginBottom: '3rem', fontSize: '1.1rem' }}>
            Versatile deployment scenarios for maximum impact.
          </p>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '2rem' }}>
            {project.applications.map((app, idx) => (
              <div key={idx} style={{ textAlign: 'center', padding: '2rem', border: '1px solid #f1f5f9', borderRadius: '1rem', background: '#fff' }}>
                <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>{app.icon}</div>
                <h3 style={{ fontSize: '1.25rem', fontWeight: 600, color: '#1e293b', marginBottom: '0.5rem' }}>{app.title}</h3>
                <p style={{ color: '#64748b', fontSize: '0.9rem' }}>{app.desc}</p>
              </div>
            ))}
          </div>
        </section>

        {/* --- DOWNLOADS/CTA SECTION --- */}
        <section id="downloads" style={{ padding: '6rem 0' }}>
          <div style={{ background: '#1e293b', borderRadius: '1.5rem', padding: '4rem 2rem', textAlign: 'center', color: 'white', position: 'relative', overflow: 'hidden' }}>
            {/* Decorative Circle */}
            <div style={{ position: 'absolute', top: '-50%', left: '-10%', width: '500px', height: '500px', background: '#3b82f6', borderRadius: '50%', opacity: 0.1, pointerEvents: 'none' }}></div>
            
            <h2 style={{ fontSize: '2.5rem', fontWeight: 700, marginBottom: '1rem', position: 'relative' }}>Ready to Deploy?</h2>
            <p style={{ color: '#cbd5e1', fontSize: '1.1rem', marginBottom: '2rem', maxWidth: '600px', margin: '0 auto 2rem auto', position: 'relative' }}>
              Download the comprehensive datasheet or contact our engineering team for a custom quote tailored to your requirements.
            </p>
            <div style={{ display: 'flex', justifyContent: 'center', gap: '1rem', flexWrap: 'wrap', position: 'relative' }}>
              <a href="#" style={{ padding: '1rem 2rem', background: 'white', color: '#1e293b', fontWeight: 600, borderRadius: '0.5rem', textDecoration: 'none' }}>
                Download Datasheet
              </a>
              <a href="mailto:contact@aiiot.edu" style={{ padding: '1rem 2rem', background: '#3b82f6', color: 'white', fontWeight: 600, borderRadius: '0.5rem', textDecoration: 'none' }}>
                Contact Sales
              </a>
            </div>
          </div>
        </section>

      </div>
      
      {/* Footer is typically in your Layout/Index, but if included here: */}
      <footer style={{ background: '#0f172a', padding: '2rem', textAlign: 'center', color: '#64748b', fontSize: '0.875rem' }}>
        <p>&copy; 2025 Center for AI-IoT Innovations. All rights reserved.</p>
      </footer>

    </div>
  );
};

export default ProjectDetail;
